import re
import datetime
import calendar
from decimal import Decimal, ROUND_HALF_UP, localcontext, InvalidOperation

_VALID = ("30/360_US", "30E/360", "ACT/365F", "ACT/ACT_ISDA")
_Q10 = Decimal("0.0000000001")
_Q2 = Decimal("0.01")

def _parse_date(s):
    if not isinstance(s, str):
        raise ValueError("bad date")
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s) is None:
        raise ValueError("bad date format")
    y = int(s[0:4])
    m = int(s[5:7])
    d = int(s[8:10])
    try:
        dt = datetime.date(y, m, d)
    except ValueError:
        raise ValueError("bad date value")
    return dt

def _check_conv(c):
    if not isinstance(c, str):
        raise ValueError("bad convention")
    if c not in _VALID:
        raise ValueError("bad convention")
    return c

def _is_last_feb(dt):
    if dt.month != 2:
        return False
    if calendar.isleap(dt.year):
        return dt.day == 29
    return dt.day == 28

def _unrounded(start_dt, end_dt, convention):
    with localcontext() as ctx:
        ctx.prec = 50
        if convention == "ACT/365F":
            days = (end_dt - start_dt).days
            return Decimal(days) / Decimal(365)
        if convention == "ACT/ACT_ISDA":
            if start_dt.year == end_dt.year:
                days = (end_dt - start_dt).days
                denom = 366 if calendar.isleap(start_dt.year) else 365
                return Decimal(days) / Decimal(denom)
            start_next = datetime.date(start_dt.year + 1, 1, 1)
            denom_s = 366 if calendar.isleap(start_dt.year) else 365
            days_first = (start_next - start_dt).days
            total = Decimal(days_first) / Decimal(denom_s)
            for y in range(start_dt.year + 1, end_dt.year):
                total += Decimal(1)
            denom_e = 366 if calendar.isleap(end_dt.year) else 365
            start_end_year = datetime.date(end_dt.year, 1, 1)
            days_last = (end_dt - start_end_year).days
            total += Decimal(days_last) / Decimal(denom_e)
            return total
        if convention == "30/360_US":
            y1, m1, d1 = start_dt.year, start_dt.month, start_dt.day
            y2, m2, d2 = end_dt.year, end_dt.month, end_dt.day
            s_last = _is_last_feb(start_dt)
            e_last = _is_last_feb(end_dt)
            a1 = d1
            if s_last:
                a1 = 30
            if d1 == 31:
                a1 = 30
            a2 = d2
            if e_last:
                if s_last:
                    a2 = 30
                else:
                    a2 = d2
            if d2 == 31:
                if a1 >= 30:
                    a2 = 30
            days360 = 360 * (y2 - y1) + 30 * (m2 - m1) + (a2 - a1)
            return Decimal(days360) / Decimal(360)
        # 30E/360
        y1, m1, d1 = start_dt.year, start_dt.month, start_dt.day
        y2, m2, d2 = end_dt.year, end_dt.month, end_dt.day
        a1 = 30 if d1 > 30 else d1
        a2 = 30 if d2 > 30 else d2
        days360 = 360 * (y2 - y1) + 30 * (m2 - m1) + (a2 - a1)
        return Decimal(days360) / Decimal(360)

def day_count_fraction(start: str, end: str, convention: str) -> Decimal:
    _check_conv(convention)
    s = _parse_date(start)
    e = _parse_date(end)
    if e < s:
        raise ValueError("end before start")
    if e == s:
        return Decimal("0.0000000000")
    frac = _unrounded(s, e, convention)
    return frac.quantize(_Q10, rounding=ROUND_HALF_UP)

def accrued_interest(principal: str, annual_rate_percent: str, start: str, end: str, convention: str) -> Decimal:
    if not isinstance(principal, str):
        raise ValueError("bad principal")
    try:
        p = Decimal(principal)
    except (InvalidOperation, ValueError):
        raise ValueError("bad principal")
    if not p.is_finite():
        raise ValueError("bad principal")
    if p < 0:
        raise ValueError("bad principal")
    if p.as_tuple().exponent < -2:
        raise ValueError("bad principal scale")
    if not isinstance(annual_rate_percent, str):
        raise ValueError("bad rate")
    try:
        r = Decimal(annual_rate_percent)
    except (InvalidOperation, ValueError):
        raise ValueError("bad rate")
    if not r.is_finite():
        raise ValueError("bad rate")
    if r < 0 or r > 100:
        raise ValueError("bad rate range")
    _check_conv(convention)
    s = _parse_date(start)
    e = _parse_date(end)
    if e < s:
        raise ValueError("end before start")
    if e == s:
        return Decimal("0.00")
    with localcontext() as ctx:
        ctx.prec = 50
        frac = _unrounded(s, e, convention)
        amt = p * (r / Decimal(100)) * frac
        return amt.quantize(_Q2, rounding=ROUND_HALF_UP)
